#!/usr/bin/env python3
"""Step 4: render PLAN.md from groups.json, extras.json, multi.json, review.json."""
import json, os, collections
HERE = os.path.dirname(os.path.abspath(__file__))
d = json.load(open(HERE + '/groups.json')); ex = json.load(open(HERE + '/extras.json')); mu = json.load(open(HERE + '/multi.json')); rv = json.load(open(HERE + '/review.json'))
L = d['languages']; g = d['groups']; o = d['one_offs']
def miss(gs): return sum(x['n_languages'] and 12 - x['n_languages'] for x in gs)
def per_lang_missing(gs):
    c = collections.Counter()
    for x in gs:
        for l in x['languages_missing']: c[l] += 1
    return c
tiers = {t: [x for x in g if x['confidence'] == t] for t in ('high', 'medium', 'low')}
prec = {}
for t, k in (('hi', 'high'), ('mid', 'medium'), ('lo', 'low')):
    r = [x for x in rv['reviewed'] if x['tier'] == t]; y = sum(x['verdict'] == 'Y' for x in r); p = sum(x['verdict'] == 'P' for x in r)
    prec[k] = (len(r), y, p)
est = sum(len(tiers[k]) * (prec[k][1] + 0.5 * prec[k][2]) / prec[k][0] for k in tiers)
by_n = collections.Counter(x['n_languages'] for x in g)
rec = collections.Counter(x['recommendation'] for x in o)
core = collections.Counter(); sib = collections.Counter(); one = collections.Counter()
for x in g:
    for m in x['members']: core[m['lang']] += 1
    for m in x['same_language_siblings']: sib[m['lang']] += 1
for x in o: one[x['lang']] += 1
def scen(f): s = [x for x in g if f(x)]; return len(s), miss(s)
S = [('A: high+medium confidence, shared by >=5 languages', lambda x: x['confidence'] != 'low' and x['n_languages'] >= 5),
     ('B: high+medium, >=4 languages', lambda x: x['confidence'] != 'low' and x['n_languages'] >= 4),
     ('C: high+medium, >=3 languages', lambda x: x['confidence'] != 'low' and x['n_languages'] >= 3),
     ('D: high+medium, >=2 languages', lambda x: x['confidence'] != 'low'),
     ('E: every candidate group (adds the low tier)', lambda x: True)]
out = []
w = out.append
w('# Test alignment plan: the un-numbered extras\n')
w('Analysis only. No template or golden was changed. Everything below is regenerated by the scripts in this directory (`scan.py`, `extract.py`, `cluster.py`, `analyze.py`, `multi.py`, `make_plan.py`; no network, no randomness) from the goldens at commit `b62e10ee2`.\n')
w('## Headline numbers\n')
tot = sum(len(v) for v in ex.values())
w(f'- **{tot} tests carry no catalogue id** ({", ".join(f"{l} {len(ex[l])}" for l in L)}). Their static scan counts match the parity check ("about 220 to 430 per language").')
w(f'- Clustering across languages produced **{len(g)} candidate behaviours that exist in 2 or more languages**, covering {sum(core.values())} tests (plus {sum(sib.values())} same-language sibling tests attached to them). The other **{len(o)} extras are one-offs** (one language only).')
w(f'- Reliability (hand-reviewed sample, see Method): high tier {len(tiers["high"])} groups, about {100*(prec["high"][1]+prec["high"][2]/2)/prec["high"][0]:.0f}% correct; medium {len(tiers["medium"])} groups, about {100*(prec["medium"][1]+prec["medium"][2]/2)/prec["medium"][0]:.0f}%; low {len(tiers["low"])} groups, about {100*(prec["low"][1]+prec["low"][2]/2)/prec["low"][0]:.0f}%. Expected number of genuinely shared behaviours: **about {est:.0f} of {len(g)}**. Recall is also imperfect (some real partners sit among the one-offs), so the true shared count is somewhat higher than the grouped count would suggest.')
w(f'- **If every candidate group were promoted into the catalogue it would add {len(g)} behaviours and {miss(g)} missing tests** (sum over groups of the languages lacking it). Promoting only high+medium groups adds {len(tiers["high"])+len(tiers["medium"])} behaviours and {miss(tiers["high"])+miss(tiers["medium"])} tests. The extras are mostly NOT shared across languages, so full alignment means writing roughly 6 to 8 thousand new tests.\n')
w('### Extras by number of languages that share them\n')
w('| languages sharing | groups | missing tests this adds |\n|---|---|---|')
w(f'| 1 (one-off) | {len(o)} | 0 (nothing to align; see recommendations) |')
for n in sorted(by_n): w(f'| {n} | {by_n[n]} | {by_n[n]*(12-n)} |')
for n in range(2, 13):
    if n not in by_n: w(f'| {n} | 0 | 0 |')
w(f'| **total shared** | **{len(g)}** | **{miss(g)}** |\n')
w('Groups sharing 10, 11 or 12 languages: none were found; the widest candidate is shared by 9 languages.\n')
w('### By confidence tier\n')
w('| tier | meaning (avg link score) | groups | languages present (tests) | missing tests |\n|---|---|---|---|---|')
for t, m in (('high', '>= 0.50'), ('medium', '0.42 to 0.50'), ('low', '0.36 to 0.42')):
    w(f'| {t} | {m} | {len(tiers[t])} | {sum(x["n_languages"] for x in tiers[t])} | {miss(tiers[t])} |')
w('\n### Promotion scenarios\n')
w('| scenario | behaviours added to the catalogue | tests to write (all languages) |\n|---|---|---|')
for n, f in S:
    a, b = scen(f); w(f'| {n} | {a} | {b} |')
w('\n### Tests each language must write, per scenario\n')
w('| language | extras today | in shared groups | one-offs | ' + ' | '.join(n.split(':')[0] for n, _ in S) + ' |\n|---|---|---|---|' + '---|' * len(S))
pl = [per_lang_missing([x for x in g if f(x)]) for _, f in S]
for l in L: w(f'| {l} | {len(ex[l])} | {core[l]} (+{sib[l]} siblings) | {one[l]} | ' + ' | '.join(str(p[l]) for p in pl) + ' |')
w('| **total** | ' + f'{tot} | {sum(core.values())} | {len(o)} | ' + ' | '.join(str(sum(p.values())) for p in pl) + ' |\n')
w('### Effort estimate\n')
w('Assumption (not measured): 10 to 15 minutes per added test, because each test is a template edit, a golden regeneration (all 12 goldens must be committed current) and a run of that language\'s suite, with CI at about 25 minutes per push. So scenario A is about ' + f'{scen(S[0][1])[1]*10/60:.0f} to {scen(S[0][1])[1]*15/60:.0f}' + f' hours, B about {scen(S[1][1])[1]*10/60:.0f} to {scen(S[1][1])[1]*15/60:.0f}, D about {scen(S[3][1])[1]*10/60:.0f} to {scen(S[3][1])[1]*15/60:.0f}, E about {scen(S[4][1])[1]*10/60:.0f} to {scen(S[4][1])[1]*15/60:.0f} hours of focused work. The estimate excludes the work of deciding which candidate is real (review of the medium and low tiers) and fixing generator bugs the new tests will expose, which on this project has been the larger part.\n')
w('## Recommendation\n')
w(f'1. Do not promote every candidate. Two-language groups are {by_n[2]} of {len(g)} and cost 10 tests each; most are two sibling SDKs that happened to regress-test the same internal. Start with scenario A or B (high+medium, 4 or 5+ languages): {scen(S[0][1])[0]} and {scen(S[1][1])[0]} behaviours, so the owner gets the broadly shared ones without paying for coincidences.')
w('2. Treat the low tier as a review queue, not a work list: about two thirds of it is wrong.')
w('3. One-offs: see the next section. The only sound way to shrink the extras without writing thousands of tests is to decide per one-off whether it is language-specific (keep, and keep it excused) or noise (delete).\n')
w('## One-off extras (single language)\n')
w('| recommendation | count | meaning |\n|---|---|---|')
w(f'| keep-language-specific | {rec["keep-language-specific"]} | packaging, README, transport-library or idiom-bound; stays excused under `*unnumbered` |')
w(f'| generalise-candidate | {rec["generalise-candidate"]} | a contract-level subject with no idiom marker; would need 11 tests each if universal. Reading 12 of them, only about 5 described a universal behaviour, so expect about 40% (about {int(rec["generalise-candidate"]*0.4)}) to be real |')
w(f'| possible-duplicate-verify-then-delete | {rec["possible-duplicate-verify-then-delete"]} | name+body similarity >= 0.62 to a numbered test in the SAME language. Reading 8, only about 2 were true duplicates; the rest were variants. Diff assertions before deleting |')
w('\nEvery one-off is listed with file, line, subject, recommendation, reason and nearest catalogue test in `groups.json` under `one_offs`.\n')
w('## Method\n')
w('1. `scan.py` (the existing static scanner, rooted at this worktree) finds tests per language; the behaviour-id rule is unchanged (first token `bhv<letters><3 digits>` after lowercasing and stripping non a-z0-9). `extract.py` records for each id-less test its file, line, subject file (SUT, normalised from the test file name) and first assertion line; `extras.json`.')
w('2. `cluster.py` normalises names (camelCase/snake/space split, filler words and bare numbers dropped, synonym fold such as throws/raises/rejects, suffix stemming), scores every cross-language pair as 0.65 idf-cosine of name tokens + 0.25 idf-cosine of string/number literals in the body + 0.10 same SUT, then merges greedily by descending score with average linkage >= 0.36 and at most one test per language per group. A second pass attaches a leftover test (score >= 0.40) to the group of its best neighbour as a same-language sibling when that group already has a test in its language; siblings are not counted as coverage.')
w('3. `analyze.py` gives each group an area by voting its members\' nearest NUMBERED tests (and a per-SUT prior), numbers it after the highest existing id in that area, and drafts the promise sentence from the most descriptive member name. **The promise sentences are drafts derived from names, not reviewed prose; a human must rewrite each before it enters `test-catalogue.txt`.** `area_margin` below about 0.1 (20 groups) means the area vote was close; check those.')
w(f'4. I read test bodies for a seeded sample (`sample.py`, verdicts in `review.json`): {sum(v[0] for v in prec.values())} groups, high {prec["high"][1]} Y + {prec["high"][2]} partial of {prec["high"][0]}, medium {prec["medium"][1]} Y + {prec["medium"][2]} partial of {prec["medium"][0]}, low {prec["low"][1]} Y of {prec["low"][0]}. Confidence labels come from those rates. All other groups are UNREVIEWED beyond the score.\n')
w('## The `| multi` ids (118 lines)\n')
cs = collections.Counter(v['cause'].split(' (')[0].split(' in ')[0] for v in mu.values())
w('Static scan, so run-time case counts are not visible. Findings:\n')
DD = sum(1 for v in mu.values() if v['cause'].startswith('one function per language, data-driven'))
w(f'- **Parametrised cases of one behaviour (fine): the large majority.** {DD} of the 118 ids have exactly one test function per language and in each language at least one of them shows a data-driven marker (each/with/Theory/parametrize/table loop). The marker regex is permissive (any `for` loop counts), so "data-driven" is an upper bound.')
w('- **Per generated scheme wrapper (fine, same behaviour once per wrapper class):** authapikey007, authbasic001/002/003, authbearer001/006/010, authscheme001/002, authscheme002, lifecycle004 and lifecycle015 repeat per wrapper (csharp 2 to 11, dart 8, rust 13, swift 2 to 13, go 2). These are one behaviour over the 13 generated wrappers.')
w('- **Genuinely different behaviours hiding under one id (should get their own ids):**')
w('  - `lifecycle004` (promise: ApiKeyAuthenticator HEADER rejects CR/LF and non-ASCII). Eleven languages test exactly that. **Swift has 13 tests tagged lifecycle004 that assert "a missing credential fails at construction" per wrapper** (ClientTests.swift line 338 onward). That is a different behaviour, mislabelled: the swift CR/LF header test is either missing or untagged. Verify and retag.')
w('  - `authscheme001` in rust: the function named `..._bhv_authscheme_001_bhv_authbasic_003_a_missing_credential_names_its_variable` carries two ids; only the first counts, so the authbasic003 claim is invisible to the parity check for that test.')
w('  - `serializationparam060` in rust has two functions: `build_query_string_encodes_reserved_by_default` and `..._keeps_reserved_when_allowed`. The promise is "wraps only when allowReserved is true", so these are the two sides of one rule (acceptable), but only rust splits them.')
w('  - `authapikey011` in csharp has two functions (ASCII-whitespace-only and form-feed-only); both are variants of the one promise (fine).')
w('- **Probably unnecessary multi flag (one function everywhere, no data-driven marker found):** authoauthtwopassword006, errors035, retries011, serializationwire014. Each bundles two claims in its promise ("refresh ... and falls back", "308 https->http ... (no body replay)"), so the single test may assert two behaviours; read the bodies before splitting.')
w('- Cannot verify statically: whether a `multi` id that is parametrised in language X runs the same number of cases in language Y. Only the test reports can show that.\n')
w('## What I could not verify\n')
w('- Run-time test counts (parametrised cases) are not visible to the static scan; `scan.py` reports Kotlin missing 22, Node 27, Dart 3, Elixir 1 ids and Swift 37 stale exceptions at this commit, so the scan and the real parity check disagree slightly (names built dynamically or ids split across lines). The extras counts could be off by a few in those languages.')
w('- Group correctness beyond the sampled 54 groups; recall of the clustering (a spot check of 16 random one-offs found about 5 with a real partner that scored below the threshold or collided on language, so the one-off list is inflated and the shared list undercounted, by an amount I can only bound loosely at between 10% and a third).')
w('- Whether a candidate is a real contract (every SDK should behave so) or a language quirk is a judgement the scores do not make; "generalise-candidate" is a heuristic flag only.')
w('- The proposed ids are provisional: numbering follows group order and will shift if any group is rejected.\n')
open(HERE + '/PLAN.md', 'w').write('\n'.join(out))
print('\n'.join(out)[:6000])
